  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import { useVaultStore } from '../stores/vault.store';
 10→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 11→import { clearAllUserStores } from '../lib/clear-user-stores';
 12→import { initSdkClient } from '../lib/sdk-provider';
 13→// api-config.ts handles setApiClientConfig at module load time
 14→import {
 15→  initializeVault,
 16→  detectBlobVersion,
 17→  deserializeVaultBlobV2,
 18→  serializeVaultBlobV2,
 19→  encryptFolderMetadata,
 20→} from '@cipherbox/core';
 21→import type { FolderMetadata } from '@cipherbox/core';
 22→import {
 23→  deriveIpnsName,
 24→  deriveVaultIpnsKeypair,
 25→  bytesToHex,
 26→  wrapKey,
 27→  unwrapKey,
 28→} from '@cipherbox/crypto';
 29→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 30→import { detectDeviceInfo } from '../lib/device/info';
 31→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 32→import { initializeBin } from '../services/bin.service';
 33→import { useBinStore } from '../stores/bin.store';
 34→import { vaultControllerGetConfig } from '@cipherbox/api-client';
 35→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../services/ipns.service';
 36→import { addToIpfs, fetchFromIpfs } from '../lib/api/ipfs';
 37→
 38→export function useAuth() {
 39→  const navigate = useNavigate();
 40→  const {
 41→    isLoggedIn: coreKitLoggedIn,
 42→    isInitialized: coreKitInitialized,
 43→    isRequiredShare,
 44→    loginWithGoogle: coreKitLoginGoogle,
 45→    loginWithEmailOtp: coreKitLoginEmail,
 46→    loginWithWallet: coreKitLoginWallet,
 47→    getVaultKeypair,
 48→    getPublicKeyHex,
 49→    logout: coreKitLogout,
 50→  } = useCoreKitAuth();
 51→  const { syncStatus } = useCoreKit();
 52→  const {
 53→    accessToken,
 54→    isAuthenticated,
 55→    lastAuthMethod,
 56→    userEmail,
 57→    setAccessToken,
 58→    setAuthenticated,
 59→    setLastAuthMethod,
 60→    setUserEmail,
 61→    setVaultKeypair,
 62→  } = useAuthStore();
 63→
 64→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 65→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 66→  const restoringRef = useRef(false);
 67→
 68→  // Stable refs for functions used in the session restoration effect.
 69→  // This prevents the effect from re-firing when function references change.
 70→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 71→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 72→
 73→  // Pending auth state for REQUIRED_SHARE flow.
 74→  // Stored in Zustand (not useState) so the state is shared across all
 75→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 76→  // via its own useAuth() call.
 77→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 78→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 79→
 80→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 81→
 82→  // Get vault store actions
 83→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 84→
 85→  /**
 86→   * Initialize vault for new users or load existing vault keys.
 87→   * Called after successful backend authentication.
 88→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 89→   */
 90→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 91→    // Get user's secp256k1 keypair from Core Kit TSS export
 92→    const userKeypair = await getVaultKeypair();
 93→
 94→    if (!userKeypair) {
 95→      throw new Error('Failed to get vault keypair from Core Kit');
 96→    }
 97→
 98→    // Store keypair in auth store for crypto operations
 99→    setVaultKeypair(userKeypair);
100→
101→    try {
102→      // Try to fetch existing vault
103→      const existingVault = await vaultApi.getVault();
104→
105→      // Store TEE keys if available
106→      if (existingVault.teeKeys) {
107→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
108→      }
109→
110→      // All users read rootFolderKey from IPFS v2 blob (no DB fallback)
111→      const ipnsKeypair = await deriveVaultIpnsKeypair(userKeypair.privateKey);
112→      const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
113→
114→      const resolved = await resolveIpnsRecord(ipnsName);
115→      if (!resolved) throw new Error('IPNS name not found for vault');
116→
117→      const blobBytes = await fetchFromIpfs(resolved.cid);
118→
119→      if (detectBlobVersion(blobBytes) !== 2) {
120→        throw new Error('Vault blob is not v2 format');
121→      }
122→
123→      const { encryptedRootFolderKey: encKey } = deserializeVaultBlobV2(blobBytes);
124→      const rootFolderKey = await unwrapKey(encKey, userKeypair.privateKey);
125→
126→      setVaultKeys({
127→        rootFolderKey,
128→        rootIpnsKeypair: ipnsKeypair,
129→        rootIpnsName: existingVault.rootIpnsName,
130→        vaultId: existingVault.id,
131→      });
132→    } catch (error) {
133→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
134→
135→      if (is404) {
136→        // New user -- initialize vault with IPFS-native v2 blob
137→        console.log('[Auth] New user -- initializing vault with v2 blob');
138→        const newVault = await initializeVault(userKeypair.privateKey);
139→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
140→
141→        // 1. ECIES-wrap rootFolderKey for v2 blob header
142→        const encryptedRootFolderKey = await wrapKey(newVault.rootFolderKey, userKeypair.publicKey);
143→
144→        // 2. Create empty folder metadata, encrypt with rootFolderKey
145→        const emptyMetadata: FolderMetadata = { version: 'v2', children: [] };
146→        const encrypted = await encryptFolderMetadata(emptyMetadata, newVault.rootFolderKey);
147→        const metadataJsonBytes = new TextEncoder().encode(JSON.stringify(encrypted));
148→
149→        // 3. Serialize as v2 blob (ECIES-wrapped key + AES-GCM metadata)
150→        const v2Blob = serializeVaultBlobV2(encryptedRootFolderKey, metadataJsonBytes);
151→
152→        // 4. Upload v2 blob to IPFS
153→        const uploadResult = await addToIpfs(new Blob([v2Blob as BlobPart]));
154→
155→        // 5. Create and publish IPNS record (sequence 0)
156→        const publishResult = await createAndPublishIpnsRecord({
157→          ipnsPrivateKey: newVault.rootIpnsKeypair.privateKey,
158→          ipnsName: rootIpnsName,
159→          metadataCid: uploadResult.cid,
160→          sequenceNumber: 0n,
161→          expectedSequenceNumber: undefined,
162→        });
163→
164→        if (!publishResult.success) {
165→          throw new Error('Failed to publish initial IPNS record for new vault');
166→        }
167→
168→        // 6. Register vault with API (no crypto fields -- IPFS-only)
169→        const storedVault = await vaultApi.initVault({
170→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
171→          rootIpnsName,
172→        });
173→
174→        if (storedVault.teeKeys) {
175→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
176→        }
177→
178→        setVaultKeys({
179→          rootFolderKey: newVault.rootFolderKey,
180→          rootIpnsKeypair: newVault.rootIpnsKeypair,
181→          rootIpnsName,
182→          vaultId: storedVault.id,
183→          isNewVault: true,
184→        });
185→      } else {
186→        console.error('[useAuth] Failed to load vault:', error);
187→        throw error;
188→      }
189→    }
190→
191→    // Initialize SDK client with decrypted vault keys
192→    const vaultState = useVaultStore.getState();
193→    const authState = useAuthStore.getState();
194→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
195→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
196→      const getAccessToken = async () => {
197→        const state = useAuthStore.getState();
198→        return state.accessToken || '';
199→      };
200→
201→      // @cipherbox/api-client is configured in lib/api-config.ts at module load time.
202→
203→      const sdkClient = initSdkClient({
204→        apiUrl,
205→        getAccessToken,
206→        vaultKeypair: {
207→          publicKey: userKeypair.publicKey,
208→          privateKey: userKeypair.privateKey,
209→        },
210→        rootIpnsName: vaultState.rootIpnsName,
211→        rootFolderKey: vaultState.rootFolderKey,
212→        teeKeys: authState.teeKeys ?? undefined,
213→        shareCallbacks: {
214→          getCoveringShares: async (folderIpnsName: string) => {
215→            const { findCoveringShares } = await import('../services/share.service');
216→            const folders = useFolderStore.getState().folders;
217→            // Find the folder ID from IPNS name for ancestor traversal
218→            const folderId =
219→              Object.keys(folders).find((id) => folders[id].ipnsName === folderIpnsName) ?? null;
220→            return findCoveringShares(folderIpnsName, folders, folderId);
221→          },
222→          addShareKeys: async (shareId, keys) => {
223→            const { addShareKeys } = await import('../services/share.service');
224→            await addShareKeys(shareId, keys);
225→          },
226→        },
227→      });
228→
229→      // Subscribe folder store to SDK events
230→      useFolderStore.getState().subscribeToSdk(sdkClient);
231→
232→      // Subscribe bin store to SDK events
233→      useBinStore.getState().subscribeToSdk(sdkClient);
234→    }
235→
236→    // Non-blocking device registry initialization (fire-and-forget)
237→    // Placed after vault load so registry failures never block login
238→    void (async () => {
239→      try {
240→        const deviceKeypair = await getOrCreateDeviceIdentity({
241→          mode: 'persisted',
242→          vaultPrivateKey: userKeypair.privateKey,
243→        });
244→        const deviceInfo = detectDeviceInfo();
245→        const result = await initializeOrSyncRegistry({
246→          userPrivateKey: userKeypair.privateKey,
247→          userPublicKey: userKeypair.publicKey,
248→          deviceKeypair,
249→          deviceInfo: { ...deviceInfo, ipHash: '' },
250→        });
251→        if (result) {
252→          useDeviceRegistryStore
253→            .getState()
254→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
255→        }
256→      } catch (error) {
257→        console.error('[Auth] Device registry init failed (non-blocking):', error);
258→      }
259→    })();
260→
261→    // Non-blocking bin initialization (fire-and-forget)
262→    // After old service creates/loads bin, also load into SDK for deleteToBin support
263→    void (async () => {
264→      try {
265→        await initializeBin({
266→          userPrivateKey: userKeypair.privateKey,
267→          userPublicKey: userKeypair.publicKey,
268→        });
269→        // Now load bin into SDK (old service ensures bin IPNS record exists)
270→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
271→        if (hasSdkClient()) {
272→          await getSdkClient().loadBin();
273→        }
274→      } catch (error) {
275→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
276→      }
277→    })();
278→
279→    // Non-blocking: fetch retention config from API
280→    void (async () => {
281→      try {
282→        const config = await vaultControllerGetConfig();
283→        if (config.recycleBinRetentionDays != null) {
284→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
285→        }
286→      } catch (error) {
287→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
288→      }
289→    })();
290→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
291→
292→  /**
293→   * Complete backend authentication after Core Kit login.
294→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
295→   * to the backend with loginType 'corekit'. The backend verifies it against
296→   * its own JWKS since CipherBox is the identity provider.
297→   */
298→  const completeBackendAuth = useCallback(
299→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
300→      // 1. Get real publicKey from Core Kit TSS export
301→      const publicKey = await getPublicKeyHex();
302→      if (!publicKey) {
303→        throw new Error('Failed to get publicKey from Core Kit');
304→      }
305→
306→      // publicKey available for debugging via DevTools if needed
307→
308→      // 2. Authenticate with CipherBox backend
309→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
310→      const response = await authApi.login({
311→        idToken: cipherboxJwt,
312→        publicKey,
313→        loginType: 'corekit',
314→      });
315→
316→      // 3. Store access token (refresh token in HTTP-only cookie)
317→      // Note: this does NOT set isAuthenticated — we wait until vault + SDK
318→      // are fully initialized to prevent Login.tsx from redirecting to /files
319→      // before the SDK client is ready for file operations.
320→      setAccessToken(response.accessToken);
321→
322→      // 4. Remember auth method for UX
323→      setLastAuthMethod(authMethod);
324→
325→      // 5. Initialize or load vault + SDK client
326→      await initializeOrLoadVault();
327→
328→      // 6. Now that vault keys are loaded and SDK is initialized,
329→      // mark the user as authenticated. This triggers Login.tsx → /files redirect.
330→      setAuthenticated();
331→    },
332→    [getPublicKeyHex, setAccessToken, setAuthenticated, setLastAuthMethod, initializeOrLoadVault]
333→  );
334→
335→  /**
336→   * Complete the login flow after REQUIRED_SHARE is resolved.
337→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
338→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
339→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
340→   */
341→  const completeRequiredShare = useCallback(async (): Promise<void> => {
342→    // Read directly from Zustand store to get fresh values — this callback
343→    // may be called from useDeviceApproval's useAuth() instance, so we
344→    // can't rely on closure-captured selector values.
345→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
346→
347→    if (!jwt || !method) {
348→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
349→    }
350→
351→    // Core Kit should now be LOGGED_IN after inputFactorKey()
352→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
353→    await completeBackendAuth(method, jwt);
354→
355→    // NOW sync Core Kit React state to LOGGED_IN.
356→    // We deliberately delayed this from inputFactorKey() to prevent the session
357→    // restoration effect from firing before backend auth completed.
358→    // At this point isAuthenticated is true (from completeBackendAuth -> setAuthenticated),
359→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
360→    syncStatus();
361→
362→    // Clear pending state
363→    setPendingAuth(null, null);
364→
365→    // Navigate to files
366→    navigate('/files');
367→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
368→
369→  /**
370→   * Login with Google OAuth token.
371→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
372→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
373→   */
374→  const loginWithGoogle = useCallback(
375→    async (googleIdToken: string): Promise<void> => {
376→      if (isLoggingIn) return;
377→      setIsLoggingIn(true);
378→      try {
379→        // 1. Core Kit login via CipherBox identity provider
380→        const {
381→          cipherboxJwt,
382→          email,
383→          userId,
384→          status: coreKitStatus,
385→        } = await coreKitLoginGoogle(googleIdToken);
386→
387→        if (coreKitStatus === 'required_share') {
388→          // MFA enabled but device factor missing.
389→          // Store pending auth info for later completion after factor input.
390→          setPendingAuth(cipherboxJwt, 'google');
391→
392→          // Obtain temporary backend access token so the new device can
393→          // call bulletin board API endpoints (device-approval/*).
394→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
395→          // state and we can't export the TSS key yet.
396→          const tempLoginResponse = await authApi.login({
397→            idToken: cipherboxJwt,
398→            publicKey: `pending-core-kit-${userId}`,
399→            loginType: 'corekit',
400→          });
401→          setAccessToken(tempLoginResponse.accessToken);
402→
403→          if (email) {
404→            setUserEmail(email);
405→          }
406→
407→          // Do NOT call completeBackendAuth() or navigate('/files')
408→          // The component tree will see isRequiredShare === true and
409→          // render recovery/approval UI.
410→          return;
411→        }
412→
413→        // Normal path: Core Kit logged in, proceed as before
414→        // 2. Complete backend auth + vault init
415→        await completeBackendAuth('google', cipherboxJwt);
416→
417→        // 3. Store email for UI display (returned from identity endpoint)
418→        if (email) {
419→          setUserEmail(email);
420→        }
421→
422→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
423→      } catch (error) {
424→        console.error('[useAuth] Google login failed:', error);
425→        throw error;
426→      } finally {
427→        setIsLoggingIn(false);
428→      }
429→    },
430→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
431→  );
432→
433→  /**
434→   * Login with Email OTP.
435→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
436→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
437→   */
438→  const loginWithEmail = useCallback(
439→    async (email: string, otp: string): Promise<void> => {
440→      if (isLoggingIn) return;
441→      setIsLoggingIn(true);
442→      try {
443→        // 1. Core Kit login via CipherBox identity provider
444→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
445→
446→        if (coreKitStatus === 'required_share') {
447→          setPendingAuth(cipherboxJwt, 'email');
448→
449→          const tempLoginResponse = await authApi.login({
450→            idToken: cipherboxJwt,
451→            publicKey: `pending-core-kit-${userId}`,
452→            loginType: 'corekit',
453→          });
454→          setAccessToken(tempLoginResponse.accessToken);
455→          setUserEmail(email);
456→          return;
457→        }
458→
459→        // Normal path
460→        await completeBackendAuth('email', cipherboxJwt);
461→        setUserEmail(email);
462→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
463→      } catch (error) {
464→        console.error('[useAuth] Email login failed:', error);
465→        throw error;
466→      } finally {
467→        setIsLoggingIn(false);
468→      }
469→    },
470→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
471→  );
472→
473→  /**
474→   * Login with Wallet (SIWE).
475→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
476→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
477→   */
478→  const loginWithWallet = useCallback(
479→    async (cipherboxJwt: string, userId: string): Promise<void> => {
480→      if (isLoggingIn) return;
481→      setIsLoggingIn(true);
482→      try {
483→        // 1. Core Kit login via CipherBox identity provider
484→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
485→
486→        if (coreKitStatus === 'required_share') {
487→          setPendingAuth(cipherboxJwt, 'wallet');
488→
489→          const tempLoginResponse = await authApi.login({
490→            idToken: cipherboxJwt,
491→            publicKey: `pending-core-kit-${userId}`,
492→            loginType: 'corekit',
493→          });
494→          setAccessToken(tempLoginResponse.accessToken);
495→          return;
496→        }
497→
498→        // Normal path
499→        await completeBackendAuth('wallet', cipherboxJwt);
500→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
501→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
502→        // inside it may still be pending. An explicit navigate here would fire AFTER
503→        // vault init completes — by which point the user may have navigated away from
504→        // the login page, causing a disruptive late redirect.
505→      } catch (error) {
506→        console.error('[useAuth] Wallet login failed:', error);
507→        throw error;
508→      } finally {
509→        setIsLoggingIn(false);
510→      }
511→    },
512→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
513→  );
514→
515→  // Complete logout: Backend -> Core Kit -> Clear state
516→  const logout = useCallback(async () => {
517→    if (isLoggingOut) return;
518→
519→    setIsLoggingOut(true);
520→    try {
521→      // 1. Call backend logout (clears cookie)
522→      if (accessToken) {
523→        try {
524→          await authApi.logout();
525→        } catch {
526→          // Ignore errors -- we'll clear state anyway
527→        }
528→      }
529→
530→      // 2. Logout Core Kit (clears session from localStorage)
531→      await coreKitLogout();
532→
533→      // 3. Clear all user-scoped stores (centralized helper)
534→      clearAllUserStores();
535→
536→      // 4. Navigate to login
537→      navigate('/');
538→    } catch (error) {
539→      console.error('[useAuth] Logout failed:', error);
540→      // Still clear state even if backend fails
541→      clearAllUserStores();
542→      navigate('/');
543→    } finally {
544→      setIsLoggingOut(false);
545→    }
546→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
547→
548→  // Keep function refs up-to-date for use in session restoration effect.
549→  // Using refs prevents the effect from re-firing when function identities change.
550→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
551→  coreKitLogoutRef.current = coreKitLogout;
552→
553→  // Session restoration: if Core Kit restores a session from localStorage
554→  // on init, we have LOGGED_IN status without going through login flow.
555→  // Complete backend auth + vault loading.
556→  useEffect(() => {
557→    const restoreSession = async () => {
558→      // Only restore if Core Kit has a session but we don't have
559→      // a backend access token yet
560→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
561→        restoringRef.current = true;
562→        setIsLoggingIn(true);
563→        try {
564→          // Try to refresh using the HTTP-only cookie first
565→          const response = await authApi.refresh();
566→          setAccessToken(response.accessToken);
567→
568→          // Restore email from backend if available
569→          if (response.email) {
570→            setUserEmail(response.email);
571→          }
572→
573→          // Load vault keys from Core Kit keypair + initialize SDK
574→          await initializeOrLoadVaultRef.current?.();
575→
576→          // Mark as authenticated only after vault + SDK are ready
577→          setAuthenticated();
578→        } catch {
579→          // No valid backend session -- user needs to re-login
580→          // Core Kit session exists but backend cookie expired
581→          // Clear Core Kit session to avoid inconsistent state
582→          try {
583→            await coreKitLogoutRef.current?.();
584→          } catch {
585→            // Ignore logout errors during cleanup
586→          }
587→        } finally {
588→          restoringRef.current = false;
589→          setIsLoggingIn(false);
590→        }
591→      }
592→    };
593→    restoreSession();
594→  }, [
595→    coreKitLoggedIn,
596→    isAuthenticated,
597→    isLoggingIn,
598→    setAccessToken,
599→    setAuthenticated,
600→    setUserEmail,
601→  ]);
602→
603→  return {
604→    isLoading,
605→    isAuthenticated,
606→    isRequiredShare,
607→    lastAuthMethod,
608→    userEmail,
609→    pendingAuthMethod,
610→    loginWithGoogle,
611→    loginWithEmail,
612→    loginWithWallet,
613→    completeRequiredShare,
614→    logout,
615→  };
616→}
