  1→//! Request and response types for the CipherBox backend API.
  2→//!
  3→//! All structs use camelCase serialization to match the API's JSON format.
  4→//! Auth DTOs use manual Debug impls to redact sensitive fields (M-11).
  5→
  6→use std::fmt;
  7→
  8→use serde::{Deserialize, Serialize};
  9→
 10→/// Login request body sent to POST /auth/login.
 11→#[derive(Serialize)]
 12→#[serde(rename_all = "camelCase")]
 13→pub struct LoginRequest {
 14→    pub id_token: String,
 15→    pub public_key: String,
 16→    pub login_type: String,
 17→}
 18→
 19→impl fmt::Debug for LoginRequest {
 20→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 21→        f.debug_struct("LoginRequest")
 22→            .field("id_token", &"[REDACTED]")
 23→            .field("public_key", &"[REDACTED]")
 24→            .field("login_type", &self.login_type)
 25→            .finish()
 26→    }
 27→}
 28→
 29→/// Login response from POST /auth/login (desktop client receives refreshToken in body).
 30→#[derive(Deserialize)]
 31→#[serde(rename_all = "camelCase")]
 32→pub struct LoginResponse {
 33→    pub access_token: String,
 34→    pub refresh_token: String,
 35→    pub is_new_user: bool,
 36→}
 37→
 38→impl fmt::Debug for LoginResponse {
 39→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 40→        f.debug_struct("LoginResponse")
 41→            .field("access_token", &"[REDACTED]")
 42→            .field("refresh_token", &"[REDACTED]")
 43→            .field("is_new_user", &self.is_new_user)
 44→            .finish()
 45→    }
 46→}
