 48→/// Refresh request body sent to POST /auth/refresh.
 49→#[derive(Serialize)]
 50→#[serde(rename_all = "camelCase")]
 51→pub struct RefreshRequest {
 52→    pub refresh_token: String,
 53→}
 54→
 55→impl fmt::Debug for RefreshRequest {
 56→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 57→        f.debug_struct("RefreshRequest")
 58→            .field("refresh_token", &"[REDACTED]")
 59→            .finish()
 60→    }
 61→}
 62→
 63→/// Refresh response from POST /auth/refresh (desktop client receives refreshToken in body).
 64→#[derive(Deserialize)]
 65→#[serde(rename_all = "camelCase")]
 66→pub struct RefreshResponse {
 67→    pub access_token: String,
 68→    pub refresh_token: String,
 69→}
 70→
 71→impl fmt::Debug for RefreshResponse {
 72→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
