  1→//! Vault initialization and decryption commands.
  2→
  3→use crate::api::types;
  4→use crate::crypto;
  5→use crate::state::AppState;
  6→
  7→/// Initialize a new vault for a first-time user.
  8→///
  9→/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
 10→/// keypair via HKDF from the user's private key. ECIES-wraps them with the
 11→/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
 12→pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
 13→    // Generate root folder AES-256 key (32 random bytes)
 14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
 15→
 16→    // Derive IPNS keypair deterministically via HKDF from user's private key
 17→    let private_key = state
 18→        .private_key
 19→        .read()
 20→        .await
 21→        .as_ref()
 22→        .ok_or("Private key not available for vault IPNS derivation")?
 23→        .clone();
 24→    let private_key_arr: [u8; 32] = private_key
 25→        .as_slice()
 26→        .try_into()
 27→        .map_err(|_| "Invalid private key length")?;
 28→    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
 29→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
 30→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
 31→
 32→    // ECIES-wrap rootFolderKey with user's uncompressed secp256k1 public key (for v2 blob header)
 33→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
 34→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
 35→
 36→    // 1. Register vault with backend (no crypto fields -- IPFS-only)
 37→    let init_req = types::InitVaultRequest {
 38→        owner_public_key: hex::encode(public_key),
 39→        root_ipns_name: root_ipns_name.clone(),
 40→    };
 41→
 42→    let resp = state
 43→        .api
 44→        .authenticated_post("/vault/init", &init_req)
 45→        .await
 46→        .map_err(|e| format!("Vault init request failed: {}", e))?;
 47→
 48→    if !resp.status().is_success() {
 49→        let status = resp.status();
 50→        let body = resp.text().await.unwrap_or_default();
 51→        return Err(format!("Vault init failed ({}): {}", status, body));
 52→    }
 53→
 54→    // 2. Create and publish initial empty folder metadata
 55→    //    Without this, FUSE init() can't resolve the root IPNS name.
 56→    log::info!("Publishing initial empty root folder metadata");
 57→
 58→    let empty_metadata = crypto::folder::FolderMetadata {
 59→        version: "v2".to_string(),
 60→        children: vec![],
 61→    };
 62→
 63→    // Encrypt metadata with root folder key and produce v2 blob
 64→    let folder_key_arr: [u8; 32] = root_folder_key
 65→        .as_slice()
 66→        .try_into()
 67→        .map_err(|_| "Invalid root folder key length".to_string())?;
 68→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
 69→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
 70→
 71→    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
 72→    use base64::Engine;
 73→    let iv_hex = hex::encode(&sealed[..12]);
 74→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
 75→    let json_metadata = serde_json::json!({
 76→        "iv": iv_hex,
 77→        "data": data_base64,
 78→    });
 79→    let json_bytes = serde_json::to_vec(&json_metadata)
 80→        .map_err(|e| format!("JSON serialization failed: {}", e))?;
 81→
 82→    // Wrap rootFolderKey in v2 blob envelope -- reuse the ECIES-wrapped key from above
 83→    let blob_bytes =
 84→        crypto::vault_blob::serialize_vault_blob_v2(&encrypted_root_folder_key, &json_bytes)?;
 85→
 86→    // Upload v2 blob to IPFS
 87→    let initial_cid = crate::api::ipfs::upload_content(&state.api, &blob_bytes).await?;
 88→
 89→    // Create and sign IPNS record (sequence 0, 24h lifetime)
 90→    let ipns_key_arr: [u8; 32] = ipns_private_key.as_slice()
 91→        .try_into()
 92→        .map_err(|_| "Invalid IPNS private key length".to_string())?;
 93→    let value = format!("/ipfs/{}", initial_cid);
 94→    let record = crypto::ipns::create_ipns_record(&ipns_key_arr, &value, 0, 86_400_000)
 95→        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
 96→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
 97→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
 98→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
 99→
100→    // Publish IPNS record via backend (sequence 0 - first ever publish, no conflict check needed)
101→    let publish_req = crate::api::ipns::IpnsPublishRequest {
102→        ipns_name: root_ipns_name.clone(),
103→        record: record_base64,
104→        metadata_cid: initial_cid,
105→        encrypted_ipns_private_key: None,
106→        key_epoch: None,
107→        expected_sequence_number: None,
108→    };
109→    match crate::api::ipns::publish_ipns(&state.api, &publish_req).await? {
110→        crate::api::ipns::PublishResult::Success => {}
111→        crate::api::ipns::PublishResult::Conflict { .. } => {
112→            // Sequence 0 should never conflict on vault init -- log and continue
113→            log::warn!("Unexpected conflict on vault init publish (sequence 0)");
114→        }
115→    }
116→
117→    log::info!("Vault initialized and root metadata published for new user");
118→    Ok(())
119→}
120→
121→/// Fetch vault from backend and decrypt rootFolderKey from IPFS v2 blob.
122→///
123→/// All users read rootFolderKey from the IPFS vault blob v2 header.
124→/// The IPNS keypair is always HKDF-derived from the user's private key.
125→/// Stores all keys in AppState (memory only).
126→pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
127→    log::info!("Fetching and decrypting vault keys");
128→
129→    // GET /vault
130→    let resp = state
131→        .api
132→        .authenticated_get("/vault")
133→        .await
134→        .map_err(|e| format!("Vault fetch failed: {}", e))?;
135→
136→    if !resp.status().is_success() {
137→        let status = resp.status();
138→        let body = resp.text().await.unwrap_or_default();
139→        return Err(format!("Vault fetch failed ({}): {}", status, body));
140→    }
141→
142→    let vault: types::VaultResponse = resp
143→        .json()
144→        .await
145→        .map_err(|e| format!("Failed to parse vault response: {}", e))?;
146→
147→    // Get private key
148→    let private_key = state
149→        .private_key
150→        .read()
151→        .await
152→        .as_ref()
153→        .ok_or("Private key not available for vault decryption")?
154→        .clone();
155→    let private_key_arr: [u8; 32] = private_key
156→        .as_slice()
157→        .try_into()
158→        .map_err(|_| "Invalid private key length")?;
159→
160→    // Derive IPNS keypair via HKDF
161→    let (ipns_priv, _ipns_pub, ipns_name) =
