 1→//! Vault initialization and decryption commands.
 2→
 3→use crate::api::types;
 4→use crate::crypto;
 5→use crate::state::AppState;
 6→
 7→/// Initialize a new vault for a first-time user.
 8→///
 9→/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
10→/// keypair via HKDF from the user's private key. ECIES-wraps them with the
11→/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
12→pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
13→    // Generate root folder AES-256 key (32 random bytes)
14→    let root_folder_key = crypto::utils::generate_random_bytes(32);
15→
16→    // Derive IPNS keypair deterministically via HKDF from user's private key
17→    let private_key = state
18→        .private_key
19→        .read()
20→        .await
21→        .as_ref()
22→        .ok_or("Private key not available for vault IPNS derivation")?
23→        .clone();
24→    let private_key_arr: [u8; 32] = private_key
25→        .as_slice()
26→        .try_into()
27→        .map_err(|_| "Invalid private key length")?;
28→    let (ipns_private_key, _ipns_public_key, root_ipns_name) =
29→        crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
30→            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;
31→
32→    // ECIES-wrap rootFolderKey with user's uncompressed secp256k1 public key (for v2 blob header)
33→    let encrypted_root_folder_key = crypto::ecies::wrap_key(&root_folder_key, public_key)
34→        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;
35→
36→    // 1. Register vault with backend (no crypto fields -- IPFS-only)
37→    let init_req = types::InitVaultRequest {
38→        owner_public_key: hex::encode(public_key),
39→        root_ipns_name: root_ipns_name.clone(),
40→    };
41→
42→    let resp = state
43→        .api
44→        .authenticated_post("/vault/init", &init_req)
45→        .await
46→        .map_err(|e| format!("Vault init request failed: {}", e))?;
47→
48→    if !resp.status().is_success() {
49→        let status = resp.status();
50→        let body = resp.text().await.unwrap_or_default();
51→        return Err(format!("Vault init failed ({}): {}", status, body));
52→    }
53→
54→    // 2. Create and publish initial empty folder metadata
55→    //    Without this, FUSE init() can't resolve the root IPNS name.
56→    log::info!("Publishing initial empty root folder metadata");
57→
58→    let empty_metadata = crypto::folder::FolderMetadata {
59→        version: "v2".to_string(),
60→        children: vec![],
61→    };
62→
63→    // Encrypt metadata with root folder key and produce v2 blob
64→    let folder_key_arr: [u8; 32] = root_folder_key
65→        .as_slice()
66→        .try_into()
67→        .map_err(|_| "Invalid root folder key length".to_string())?;
68→    let sealed = crypto::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
69→        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
70→
71→    // Format as JSON { "iv": "<hex>", "data": "<base64>" }
72→    use base64::Engine;
73→    let iv_hex = hex::encode(&sealed[..12]);
74→    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
75→    let json_metadata = serde_json::json!({
76→        "iv": iv_hex,
77→        "data": data_base64,
78→    });
